CREATE TABLE IF NOT EXISTS "system_electronic_signature" (
    "id" bigint generated by default as identity not null,
    "tenant_id" bigint not null,
    "module_code" varchar(64) not null,
    "action_code" varchar(64) not null,
    "subject_type" varchar(64) not null,
    "subject_id" varchar(2048) not null,
    "subject_version" varchar(128) not null,
    "actor_id" bigint not null,
    "meaning_code" varchar(64) not null,
    "meaning_label" varchar(128) not null,
    "reason" varchar(500) not null,
    "signed_at" timestamp not null,
    "time_evidence_id" varchar(128) not null,
    "authentication_method" varchar(64) not null,
    "content_hash" char(64) not null,
    "before_content_hash" char(64),
    "after_content_hash" char(64),
    "canonical_content_json" varchar(4000) not null,
    "before_content_json" varchar(4000),
    "after_content_json" varchar(4000),
    "field_diff_json" varchar(4000),
    "evidence_hash" char(64) not null,
    "algorithm" varchar(32) not null,
    "key_version" varchar(64) not null,
    "policy_version" varchar(64) not null,
    "verification_status" varchar(32) not null,
    "idempotency_key" varchar(512) not null,
    "command_hash" char(64) not null,
    "process_instance_id" varchar(128),
    "task_id" varchar(128),
    "node_code" varchar(64),
    "node_order" int,
    "creator" varchar(64) default '',
    "create_time" timestamp not null default current_timestamp,
    "updater" varchar(64) default '',
    "update_time" timestamp not null default current_timestamp,
    "deleted" bit not null default false,
    primary key ("id"),
    unique ("tenant_id", "idempotency_key", "deleted")
);


CREATE TABLE IF NOT EXISTS "mes_pqc_inspection_piece_detail" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "task_id" bigint NOT NULL,
    "sample_no" int NOT NULL,
    "item_code" varchar(64) NOT NULL,
    "item_name" varchar(128) NOT NULL,
    "inspection_method" varchar(512) NOT NULL,
    "standard_text" varchar(1024) NOT NULL,
    "selected_equipment_id" bigint,
    "selected_equipment_code" varchar(64),
    "selected_equipment_name" varchar(128),
    "selected_equipment_number" varchar(128),
    "standard_lower_limit" decimal(20,8),
    "standard_upper_limit" decimal(20,8),
    "standard_unit" varchar(32),
    "standard_precision" int,
    "result_type" varchar(32) NOT NULL,
    "item_result" varchar(64),
    "measured_value" varchar(128),
    "judgement" varchar(32),
    "simulated" boolean,
    "simulation_stage" varchar(64),
    "simulation_run_id" varchar(128),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" boolean NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    UNIQUE ("tenant_id", "task_id", "sample_no", "item_code", "deleted")
);

DELETE FROM "system_electronic_signature";
DELETE FROM "mes_pqc_inspection_piece_detail";
